def samp(p,y):  # linear interp
    if y<0 or y>=479: return None
    i=int(y); f=y-i; return p[i]*(1-f)+p[i+1]*f
def cost(t,a,p):
    s=0;n=0
    for y in range(214,252):
        y0=(y-t)/a
        v=samp(ref,y0)
        if v is None: continue
        d=p[y]-v; s+=d*d; n+=1
    return s/n
res={}
