from PIL import Image
def smooth(p,passes=3):
    for _ in range(passes):
        p=[(p[max(0,y-1)]+2*p[y]+p[min(479,y+1)])/4 for y in range(480)]
    return p
def avgprof(files):
    acc=[0.0]*480
    n=0
    for fn in files:
        im=Image.open(fn).convert('L'); px=im.load()
        for x in range(304,341):
            for y in range(480): acc[y]+=px[x,y]
        n+=1
    return smooth([v/(n*37) for v in acc])
def crestpos(p):
    out=[]
    for y in range(203,265):
        if p[y]<p[y-1] and p[y]<=p[y+1] and p[y]<p[y-2]-0.3 and p[y]<p[y+2]-0.3:
            d=(p[y-1]-p[y+1])/2; dd=p[y-1]-2*p[y]+p[y+1]
            off=d/dd if dd>0 else 0
            off=max(-0.5,min(0.5,off))
            yp=y+off
            if out and yp-out[-1]<3: continue
            out.append(yp)
    return out
